INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(19, 'plPL', 'Tharil\'zun', 'Harcownicy i renegaci Czarnej Skały urządzają zasadzki między tym miejscem a Twierdzą Kamiennej Straży. Harcownikami dowodzi ork imieniem Tharil\'zun – to jego chcemy. Przynieś mi głowę Tharil\'zuna!', 'Przynieś głowę Tharil\'zuna marszałkowi Marrisowi w Rudej Grani.', '', 'Wróć do marszałka Marrisa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(20, 'plPL', 'Zagrożenie ze strony Czarnej Skały', 'Orkowie z klanu Czarnej Skały przybyli z Płonących Stepów i zajęli Twierdzę Kamiennej Straży na północy. Stamtąd pustoszą tereny na północ od Jeziernych Włości i trzymają mieszkańców w mieście, zamkniętych jak bydło w zagrodzie.$B$BPomóż uwolnić Jezierne Włości od tego zagrożenia. Zabijaj orków z Czarnej Skały i przynieś mi na dowód dziesięć ich sfatygowanych w boju toporów.$B$BI choć Czarna Skała zagraża nam od północy, dostajemy meldunki o kolejnych orkach w południowo-wschodnim zakątku Rudej Grani. Jeśli jakichś tam znajdziesz, ich także trzeba wytropić.', 'Przynieś 10 sfatygowanych w boju toporów marszałkowi Marrisowi w Jeziernych Włościach.', '', 'Wróć do marszałka Marrisa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(34, 'plPL', 'Nieproszony gość', 'Znowu ktoś stratował i splądrował mój ogród. I wiem, który to osiłek. To ten przeklęty dzik, którego marszałek Marris zaczął nazywać Brzuchożerem.$b$bTeraz nie zdołam posadzić żonkili aż do następnego sezonu. Wszystko zniszczone! Wszystko przez tego jednego groźnego dzika. Skończ z tym szkodnikiem! Pokaż mi jego kieł, a chętnie cię wynagrodzę. Zwykle ryje w polu na południowy zachód od Jeziernych Włości, ale czasem zapuszcza się tutaj, do mojego ogrodu.', 'Martie Jainrose z Jeziernych Włości chce, żebyś $gzabił:zabiła; Brzuchożera. Przynieś jej na dowód jego kieł.', '', 'Wróć do Martie Jainrose w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(89, 'plPL', 'Most Sennych Włości', 'Podczas ostatniego najazdu orków musieliśmy przetopić całe żelazo na kule, miecze i zbroje. Posłaliśmy do Wichrogrodu po nową dostawę materiałów, ale banda gnoli z Rudej Grani napadła na karawanę i uciekła z łupem na wzgórza za Jeziernymi Włościami.$b$bTeraz brakuje nam materiałów do odbudowy mostu. Jeśli przyniesiesz mi 5 żelaznych pik i 5 żelaznych nitów, $N, dopilnuję, żebyś $gdostał:dostała; nagrodę.$b$bA teraz do roboty!', 'Przynieś 5 żelaznych pik i 5 żelaznych nitów brygadziście Oslowowi w Jeziernych Włościach.', '', 'Wróć do brygadzisty Oslowa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(91, 'plPL', 'Prawo Solomona', 'Wróg Wichrogrodu osiadł na wschodnich pogórzach Rudej Grani. Ten nikczemny złoczyńca posługuje się tajemną mocą, by siać strach i niedolę w naszym mieście i wśród naszych ludzi. Swoje plugawe interesy prowadzi pod imieniem Morganth.$b$bMorganth podporządkował sobie klan gnoli z Cienioskórych, który wykonuje jego rozkazy. Zgodnie z prawem Jeziernych Włości pomoc przestępcy działającemu przeciw Królestwu karana jest śmiercią.$b$bTe podłe gnole muszą zginąć!$b$bOddaj mi 10 wisiorów Cienioskórych, a zostaniesz $gnagrodzony:nagrodzona;.', 'Przynieś 10 wisiorów Cienioskórych wójtowi Conacherowi w Ratuszu w Jeziernych Włościach.', '', 'Wróć do wójta Conachera w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(92, 'plPL', 'Gulasz z Rudej Grani', 'Nic nie sprawiłoby mi większej radości niż ugotowanie ci gulaszu z Rudej Grani. Jest jednak mały kłopot. Podczas niedawnej rebelii orków żywiłam całą brygadę żołnierzy z Wichrogrodu. Moja spiżarnia świeci pustkami. Ale jeśli dostarczysz mi składniki, z przyjemnością spełnię twoje życzenie.$b$bPrzynieś mi tylko pięć kawałków twardego mięsa kondora, pięć ryjów wielkich krwawokłów i pięć porcji chrupiącego pajęczego mięsa.', 'Kucharka Breanna z Jeziernych Włości potrzebuje pięciu kawałków twardego mięsa kondora, pięciu ryjów wielkich krwawokłów i pięciu porcji chrupiącego pajęczego mięsa.', '', 'Wróć do kucharki Breanny w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(115, 'plPL', 'Magia cienia', 'Orkowie z Czarnej Skały zwerbowali miotaczy cieni do pomocy w atakach na Rudą Grań, a ci przynieśli ze sobą przedmioty mrocznej mocy – kule głębokiej nocy. Kule te zadały dotkliwe ciosy obrońcom Rudej Grani, dlatego musimy koniecznie usunąć te skażone przez demony przedmioty z pola walki.$B$BZnajdź kule głębokiej nocy przy zabitych miotaczach cieni Czarnej Skały i przynieś mi je. Każę się ich pozbyć, bo bez nich ten świat będzie lepszy!', 'Przynieś 3 kule głębokiej nocy marszałkowi Marrisowi w Jeziernych Włościach.', '', 'Wróć do marszałka Marrisa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(116, 'plPL', 'Czasy posuchy', 'Mam tu niezły kłopot, $N. Butelki prawie wyschły. Ostatnia dostawa trunków dawno powinna tu być. Ten najazd orków to istne piekło.$b$bMoże popracujesz dla mnie?$b$bMusisz odebrać baryłkę lagera Gromowarów od Grimbooze\'a Gromowara na wzgórzach Zachodniego Skraju, beczułkę merlota z Wichrogrodu, butelkę bimbru z Mrocznych Włości i bukłak słodkiego rumu ze Złotych Włości. Przynieś mi to wszystko, a dopilnuję, żebyś $gdostał:dostała; nagrodę.', 'Barman Daniels z Jeziernych Włości potrzebuje baryłki lagera Gromowarów, beczułki merlota, butelki bimbru i bukłaka słodkiego rumu.', '', 'Wróć do barmana Danielsa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(122, 'plPL', 'Łuski z podbrzusza', 'Potrzebuję łusek z podbrzusza piskląt czarnego smoka, żeby zapłacić za podkowy, które Argus przysłał mi ze Złotych Włości. Jeśli zdobędziesz dla mnie 6 sztuk, część oddam Argusowi... a z reszty zrobię coś dla ciebie.$B$BPisklęta czarnego smoka często latają na południe od Jeziernych Włości, ale lubią się włóczyć. Może po prostu będziesz $gmusiał:musiała; mieć oczy szeroko otwarte i polować na nie, gdy tylko je zobaczysz.', 'Zbierz 6 brzusznych łusek pisklęcia z piskląt czarnego smoka i zanieś je Vernerowi Osgoodowi w Rudej Grani.', '', 'Wróć do Vernera Osgooda w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(124, 'plPL', 'Ujadanie gnoli', 'Jakby mało było napadających orków! Teraz po grani na północ od mojej stajni krążą gnole – osiłki i mistycy – i porywają moje konie, gdy któryś się oddali...$B$BJeśli pozbędziesz się tych gnoli, moje konie i ja będziemy ci bardzo wdzięczni.', 'Zabij 10 osiłków z Rudej Grani i 8 mistyków z Rudej Grani, a następnie wróć do Vernera Osgooda.', '', 'Wróć do Vernera Osgooda w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(125, 'plPL', 'Zaginione narzędzia', 'Naprawdę przydałaby mi się pomoc, $N. Miasto jest oblężone, więc trudno o zaopatrzenie. Moje narzędzia miały przyjechać wozem ze Złotych Włości, ale most wyleciał w powietrze. Załadowaliśmy narzędzia na łódź, ale orkowie trafili w nią z katapulty. Jak zwykle mam pecha – moja skrzynka z narzędziami poszła prosto na dno jeziora.$b$bWyłów moją skrzynkę, $N, a opłaci ci się to.', 'Brygadzista Oslow z Jeziernych Włości chce, żebyś $gwyłowił:wyłowiła; jego skrzynkę z narzędziami z dna Jeziora Sennych Włości.', '', 'Wróć do brygadzisty Oslowa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(126, 'plPL', 'Wycie na wzgórzach', '$N, gnole wciąż tam są. Słyszę ich ujadanie, kiedy polują na wzgórzach nad Jeziernymi Włościami. A jeden głos jest głośniejszy od reszty – to Wyjec, ich przywódca.$B$BZabij Wyjca i rozpędź jego sforę! Przynieś mi na dowód jego łapę.$B$BI uważaj, ten gnol nie bez powodu jest ich przywódcą. To nie byle kundel...', 'Przynieś łapę Wyjca Vernerowi Osgoodowi w Jeziernych Włościach.', '', 'Wróć do Vernera Osgooda w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(127, 'plPL', 'Na sprzedaż ryby', 'Jezioro Sennych Włości słynie z cętkowanych bassów słonecznych. Zawsze jest na nie popyt... a mnie się kończą!$B$BPrzynieś mi 10 sztuk, a dobrze na nich zarobisz. Jeśli nie umiesz łowić ryb, to... może odbierzesz je murlokom!', 'Przynieś 10 cętkowanych bassów słonecznych zarządcy portu Barenowi w Jeziernych Włościach.', '', 'Wróć do zarządcy portu Barena w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(128, 'plPL', 'Nagroda za Czarną Skałę', 'Klan Czarnej Skały musi zostać zniszczony. Wróg najechał nasze ziemie. Te góry podlegają zwierzchniej władzy króla Wichrogrodu. Z naszych źródeł wiemy, że dowódcy poszczególnych oddziałów klanu zwą się czempionami. Znajdziesz ich w obozowisku na północy, tuż na zachód od drogi do Płonących Stepów.$b$bSędzia Solomon chce śmierci tych plugawych bestii. Zabij 15 czempionów Czarnej Skały i wróć do mnie.', 'Zabij 15 czempionów Czarnej Skały, a strażnik Howe w Jeziernych Włościach cię wynagrodzi.', '', 'Wróć do strażnika Howe\'a w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(129, 'plPL', 'Darmowy posiłek', 'Wyświadczysz mi przysługę? Przygotowałam posiłek dla strażnika Parkera, ale on jest na patrolu... To duży, silny strażnik z Wichrogrodu, który potrafi się obronić, ale dla zwykłej mieszkanki miasta, takiej jak ja, jest tam o wiele za niebezpiecznie.$B$BJeśli więc zaniesiesz mu posiłek ode mnie, a potem tu wrócisz, dostaniesz ode mnie darmowy posiłek! Parker patroluje odcinek drogi prowadzący do Kniei Zmierzchu.', 'Zanieś posiłek Parkera strażnikowi Parkerowi. Patroluje on drogę prowadzącą do Mrocznych Włości.', '', '', '', '', '', '', 0),
(130, 'plPL', 'Wizyta u zielarki', 'Zanim wrócisz do Darcy, możesz zanieść jej ode mnie kwiaty? Dostaniesz je w sklepie zielarki w Jeziernych Włościach, w zachodniej części miasta.$B$BAle kiedy będziesz odbierać kwiaty... nie mów zielarce, Martie, od kogo są ani dla kogo...', 'Porozmawiaj z zielarką z Rudej Grani, Martie Jainrose.', '', '', '', '', '', '', 0),
(131, 'plPL', 'Dostarczenie żonkili', 'Oto twój bukiet. Wybrałam dla ciebie żonkile. To moje ulubione kwiaty!', 'Daj Darcy bukiet żonkili.', '', '', '', '', '', '', 0),
(145, 'plPL', 'Posłaniec do Mrocznych Włości', 'Znów potrzebuję twojej pomocy. Napisałem do lorda Ebonlocke\'a z prośbą, by przysłał swoich wyszkolonych strażników, Nocną Straż, do obrony Jeziernych Włości. Ta wiadomość musi do niego szybko dotrzeć. Zachowaj najwyższą ostrożność. Ebonlocke jest burmistrzem Mrocznych Włości, w samym sercu Kniei Zmierzchu. Nie zbaczaj z dróg.', 'Sędzia Solomon chce, żebyś $gzaniósł:zaniosła; list lordowi Ebonlocke\'owi w Mrocznych Włościach.', '', '', '', '', '', '', 0),
(146, 'plPL', 'Posłaniec do Mrocznych Włości', 'Gdybym nie znał osobiście sędziego Solomona, powiedziałbym, że postradał zmysły. Mam wysłać Nocną Straż do Jeziernych Włości, bo Wichrogród odmawia pomocy? Nocna Straż powstała właśnie dlatego, że Wichrogród nas opuścił, gdy ta plugawa magia przesiąknęła tę ziemię. Gdybym wysłał Nocną Straż, zło opanowałoby to miasto, zanim strażnicy dotarliby choćby do skraju lasu.$b$bZanieś ten list z odpowiedzią swojemu zwierzchnikowi w Jeziernych Włościach.', 'Wróć do sędziego Solomona z listem z odpowiedzią od lorda Ebonlocke\'a.', '', '', '', '', '', '', 0),
(150, 'plPL', 'Murloczy kłusownicy', 'Murloki stają się problemem. Coraz większe grupy tych rybiludzi zarzucają kotwicę na brzegach Jeziora Sennych Włości i łowią ryby na potęgę! Musimy się ich pozbyć, zanim wyjedzą wszystkie ryby w jeziorze!$B$BPoluj na murloki! Przynieś mi osiem ich płetw, a może coś dla ciebie znajdę...', 'Przynieś 8 płetw murloka zarządcy portu Barenowi w Jeziernych Włościach.', '', 'Wróć do zarządcy portu Barena w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(169, 'plPL', 'Poszukiwany: Gath\'Ilzogg', 'Poszukiwany! Gath\'Ilzogg, przywódca ataków Czarnej Skały na Twierdzę Kamiennej Straży i napaści na osadę Jezierne Włości.$b$bGath\'Ilzogg jest niezwykle niebezpieczny. Według doniesień zaszył się w niedawno zdobytej twierdzy, gdzie planuje kolejne zbrodnie klanu Czarnej Skały przeciwko ludzkości. Orkową plagę trzeba zdławić za wszelką cenę. Sowita nagroda czeka na każdą odważną duszę, która dostarczy głowę Gath\'Ilzogga sędziemu Solomonowi.', 'Zabij Gath\'Ilzogga i przynieś jego głowę sędziemu Solomonowi w Jeziernych Włościach, by odebrać nagrodę.', '', 'Wróć do sędziego Solomona w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(180, 'plPL', 'Poszukiwany: porucznik Kłoszarp', 'Poszukiwany: porucznik Kłoszarp$b$bZnany przywódca klanu gnoli z Cienioskórych, działający na rozkaz Morgantha, wroga osady i Królestwa. Z polecenia sędziego Solomona ten podły zdrajca Wichrogrodu jest poszukiwany martwy. Na dowód jego śmierci pokaż sędziemu jego łapę.', 'Zabij porucznika Kłoszarpa i wróć z jego łapą do sędziego Solomona w Jeziernych Włościach.', '', 'Wróć do sędziego Solomona w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(219, 'plPL', 'Zaginiony w akcji', 'Nareszcie przyjaciele Przymierza!$b$bPomocy... proszę...$b$bOstatnie, co pamiętam, to jak te plugawe orki rozgromiły nasz oddział. Większość ludzi zginęła. Dostałem mocny cios w głowę i wszystko spowiła ciemność. Teraz jestem więźniem w tej jaskini. Pomóż mi, jestem ciężko ranny.$b$bBędę potrzebował pomocy, żeby wrócić do miasta... proszę... jesteś moją ostatnią nadzieją...', 'Chroń kaprala Keeshana w drodze powrotnej do Rudej Grani.', 'Odeskortuj kaprala Keeshana z powrotem do Rudej Grani', 'Wróć do marszałka Marrisa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(244, 'plPL', 'Nadciągające gnole', 'Witaj. Mam rozkaz patrolować ten odcinek drogi. Choć na razie jest tu bezpiecznie, widziałem obozowiska gnoli na północ i na wschód stąd.$B$BJezierne Włości muszą się dowiedzieć, że gnole zbierają siły! Zamelduj się u zastępcy Feldona w Jeziernych Włościach i powiedz mu o gnolach. Zrób to, a na pewno Feldon wypłaci ci żołd zwiadowcy.$B$BFeldon zwykle patroluje teren na południe od mostu do Jeziernych Włości.', 'Zamelduj się u zastępcy Feldona przy moście na południe od Jeziernych Włości w Górach Rudej Grani.', '', '', '', '', '', '', 0),
(246, 'plPL', 'Ocena zagrożenia', 'Nie mamy ludzi do stracenia, ale coś trzeba zrobić z gnolami, o których mi $gdoniosłeś:doniosłaś;.$B$BPrzeszukaj południową część Rudej Grani w poszukiwaniu gnoli. Nękaj je, zabij tyle, ile zdołasz, i wróć do mnie z raportem o ich liczebności i o tym, jak poważne stanowią zagrożenie. Obozowiska gnoli znajdziesz wzdłuż całej południowej drogi Rudej Grani.$B$BZrób to dla Armii Wichrogrodu, $N, a zostaniesz $gnagrodzony:nagrodzona;.', 'Zabij 10 kundli z Rudej Grani i 6 kłusowników z Rudej Grani, a następnie złóż raport zastępcy Feldonowi w Jeziernych Włościach.', '', 'Wróć do zastępcy Feldona w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(248, 'plPL', 'Dalsze poszukiwania', 'Obserwuję Wieżę Ilgalara i wyczuwam, że Morganth jest w konflikcie z orkami z Twierdzy Kamiennej Straży. Nie znam przyczyny ich sporu, ale możesz mi pomóc rozwikłać tę zagadkę.$B$BWeź kolejny Glif Azory, a potem wejdź na szczyt nietkniętej wieży strażniczej obok Twierdzy Kamiennej Straży.$B$BZnajdź odpowiedni przedmiot, w którym umieścisz glif. Skrzynia albo słój – jakieś miejsce, gdzie glif nie zostanie zauważony – wystarczy do moich celów.', 'Wejdź na nietkniętą wieżę strażniczą obok Twierdzy Kamiennej Straży w Górach Rudej Grani.$B$BZnajdź odpowiedni pojemnik, w którym umieścisz Glif Azory.', '', '', '', '', '', '', 0),
(386, 'plPL', 'Kto sieje wiatr...', 'Targorr Straszliwy służył pod Gath\'Ilzoggiem jako najwyższy kat. Jego metody były bezlitosne nawet jak na plugawych orków. Ludzie, którzy dzielnie walczyli w obronie Królestwa, byli torturowani dla jego kaprysu. Teraz siedzi w wichrogrodzkich Kazamatach, skazany na śmierć. A jednak coś tu nie gra. Jeden z urzędniczych szlachciców wstrzymał jego egzekucję. Jestem pewien, że szykuje się jakaś podłość.$b$bSkończ z Targorrem Straszliwym, $N. Udaj się do Kazamat i zetnij mu głowę, zanim spotka nas jakiś podstęp.', 'Przynieś głowę Targorra Straszliwego strażnikowi Bertonowi w Jeziernych Włościach.', '', 'Wróć do strażnika Bertona w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(1699, 'plPL', 'Próba Rethbanu', 'Moje wyzwanie nazywam Próbą Rethbanu. Żeby ją przejść, wystarczy wejść do Jaskiń Rethbanu, dotrzeć do pierwszego rozwidlenia i wrócić tutaj. Łatwizna! Tyle że jest kilka haczyków...$B$BMusisz wrócić w ciągu godziny.$B$BPo drodze roi się od gnoli z Rudej Grani.$B$BZanim zaczniesz, musisz pociągnąć łyk firmowego trunku mojej rodziny: Parzącego Jęczmiennego Browaru!$B$BTo co ty na to? Jaskinie Rethbanu leżą na pogórzu na północ od Jeziernych Włości. Jesteś $ggotów:gotowa; stawić czoła Próbie Rethbanu?', 'Wejdź do Jaskiń Rethbanu, dotrzyj do pierwszego rozwidlenia i wróć do Yorusa Jęczmieniowara w wyznaczonym czasie.$B$BNie możesz zginąć i uwolnić ducha.', 'Wejdź do Jaskiń Rethbanu', 'Wróć do Yorusa Jęczmieniowara nad Jeziorem Sennych Włości w Górach Rudej Grani.', '', '', '', '', 0),
(2282, 'plPL', 'Młyn Althera', 'Od lat szkolimy tu złodziei! W końcu nie każdy łobuz rodzi się z gracją i finezją starego Luciusa.$B$BKawałek od drogi, w górę, znajdziesz Młyn Althera. Mam tam skrzynię, a w niej coś ważnego. Przynieś mi to! Wróć z tym żetonem, a dostaniesz swój Certyfikat złodziejstwa!', 'Otwórz kasetkę Luciusa, odzyskaj Żeton złodziejstwa i zwróć go Luciusowi w Jeziernych Włościach.', '', 'Wróć do Luciusa w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(2358, 'plPL', 'Rogi Nez\'ry', 'Wiele lat temu Rogi Nez\'ry zostały skradzione z dworu w Krukowisku. Szukałem ich na wielu kontynentach i za oceanami, by w końcu odkryć, że przez cały czas miały je te nędzne bestie.$B$BZabijaj każdego orka z Czarnej Skały, na jakiego trafisz, aż odzyskasz Rogi Nez\'ry. Jeśli je zdobędziesz, znajdź mnie w Jeziernych Włościach.$B$BZrób to dla mnie, a twoje imię pozna Krukowisko, $N.', 'Zwróć Rogi Nez\'ry Arantirowi w Jeziernych Włościach.', '', 'Wróć do Arantira w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0),
(3741, 'plPL', 'Naszyjnik Hilary', 'Moja przyjaciółka Hilary zgubiła naszyjnik i nie możemy go znaleźć. Cały dzień łowiliśmy tu ryby i już tu wszystko przeszukaliśmy. Jedyne, co przychodzi mi do głowy, to że wpadł do jeziora. Rodzice nie pozwalają nam pływać w jeziorze... mama mówi, że pod wodą są jakieś złe stwory, ale ty nie wyglądasz, jakbyś się $gbał:bała; złych stworów.$B$BMożesz go dla niej znaleźć? Proszę!', 'Znajdź naszyjnik Hilary i oddaj go Hilary w Jeziernych Włościach.', '', 'Wróć do Hilary w Jeziernych Włościach w Górach Rudej Grani.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(19, 'plPL', 'Tharil\'zun był okrutnym i przebiegłym orkiem. Dobra robota – na pewno nie dał się łatwo pokonać. Oto twoja nagroda, $N.', 0),
(20, 'plPL', 'Dzięki. Mamy teraz o wielu orków mniej na głowie.', 0),
(34, 'plPL', 'Nareszcie ten postrach zniknął na dobre! Dziękuję, $N, $gwyświadczyłeś:wyświadczyłaś; mi ogromną przysługę. W tym sezonie mój ogród rozkwitnie w pełni!', 0),
(89, 'plPL', 'Świetna robota, $N. Te materiały bardzo pomogą przy budowie mostu. Postawimy tę piękność na nogi w mgnieniu oka.', 0),
(91, 'plPL', 'Sąd Jeziernych Włości docenia twoje oddanie sprawiedliwości, $N. Egzekwując prawa Królestwa, $gpomogłeś:pomogłaś; strzec sprawiedliwości w tej krainie.', 0),
(92, 'plPL', 'Dobra robota, $N. I jakie piękne okazy! A oto twój przysmak – słynny gulasz z Rudej Grani!', 0),
(115, 'plPL', 'Dziękuję, $N. Natychmiast odeślę je do zniszczenia.', 0),
(116, 'plPL', 'Kawał dobrej roboty, $N! Dobrze wiem, jakie drogi $gmusiałeś:musiałaś; przemierzyć, żeby zdobyć ten wyborny zestaw trunków. Za to moi goście znów będą zadowoleni!$b$bMoja żona to świetna krawcowa. Przyjmij, proszę, ten płaszcz, który uszyła, w podzięce za twoje usługi.', 0),
(122, 'plPL', 'Dzięki! Dzięki nim wyjdę z długów u Argusa...', 0),
(124, 'plPL', 'Dziękuję za całą twoją pomoc, $N.', 0),
(125, 'plPL', 'Wspaniale, że je $godzyskałeś:odzyskałaś;, $N! Nie sądziłem, że jeszcze kiedyś zobaczę te narzędzia.', 0),
(126, 'plPL', 'Jeszcze raz dziękuję za pomoc. Armia Wichrogrodu jest tak zajęta orkami, że nie ma ludzi, by chronić Rudą Grań przed miejscowymi zagrożeniami, takimi jak gnole.', 0),
(127, 'plPL', 'Miło się z tobą robi interesy, kamracie!', 0),
(128, 'plPL', 'Widzę, że dzielnie $gwalczyłeś:walczyłaś; z klanem Czarnej Skały, $N. Twoja służba dla naszej osady jest doprawdy wielka.', 0),
(129, 'plPL', 'Dzięki, naprawdę przyda mi się coś do zjedzenia. Pilnowanie Jeziernych Włości przed orkami i gnolami to ciężka robota!', 0),
(130, 'plPL', 'Potrzebujesz bukietu kwiatów? Niedługo jesteś w mieście... czyżby ktoś już zdążył skraść ci tu serce?$B$BWiem, że nie powinnam się wtrącać, ale miło widzieć, że miłość wisi w powietrzu... zwłaszcza w tak niebezpiecznych czasach jak te.', 0),
(131, 'plPL', 'Och, są śliczne! Nie mogę się doczekać, aż wstawię je do wody!$b$bAle... to ulubione kwiaty Martie. Chyba Parker nie posłał cię po ten bukiet do tej zazdrosnej jędzy? Chyba nie $gpowiedziałeś:powiedziałaś; jej, dla kogo są? Bo jeśli tak, nie zdziwiłabym się, gdyby je otruła.$b$bAch, ale to nie twoja wina. Dziękuję, a oto twój posiłek.', 0),
(145, 'plPL', 'Dziękuję, że $godbyłeś:odbyłaś; tak daleką podróż. To naprawdę ważne wieści.', 0),
(146, 'plPL', 'Na Światłość! Armia Wichrogrodu wycofała się z Zachodniego Skraju. A straż nie chroni już Mrocznych Włości? To musi być jakaś zdrada. Jak to możliwe?$b$bAch, zapomniałem wynagrodzić twoją służbę, $N. Oto kilka monet. A teraz wybacz. W Wichrogrodzie dzieje się coś złego i muszę dojść, o co chodzi.', 0),
(150, 'plPL', 'Dobra robota, $N. Mam nadzieję, że murloki nie sprawiły ci zbyt wielkich kłopotów.$B$BDziwnie jest widzieć je tak daleko od morza. Ciekawe, czy nie przyszły tu, uciekając przed czymś...', 0),
(169, 'plPL', 'Znakomita robota, $N! Gath\'Ilzogg prowadził te bestie do boju i zabił wielu niewinnych ludzi. Sprawiedliwości stało się zadość. To pierwszy krok do odzyskania twierdzy dla królestwa Wichrogrodu!', 0),
(180, 'plPL', 'A więc nikczemny porucznik Kłoszarp nie żyje? Dobrze, że świat pozbył się tej plugawej kreatury. Wielka z ciebie odwaga, $N. Osada Jezierne Włości dziękuje ci za pomoc.', 0),
(219, 'plPL', '$GDobrze przysłużyłeś:Dobrze przysłużyłaś; się Królestwu, $N. Dziękuję, że $gpomogłeś:pomogłaś; kapralowi Keeshanowi uciec od tych przeklętych orków z Czarnej Skały. Za dzisiejsze męstwo czeka cię nagroda.', 0),
(244, 'plPL', 'Gnole z Rudej Grani tak blisko Elwynn?! Mogą szykować się do wtargnięcia na naszą ojczystą ziemię. Wkrótce mieszkańcy Jeziernych Włości mogą nie być jedynymi oblężonymi ludźmi!$b$bOto twoja zapłata, choć przynosisz złe wieści. I to w złym momencie, bo nie jesteśmy przygotowani, by stawić im czoła.', 0),
(246, 'plPL', '<Zastępca Feldon wysłuchuje twojego raportu...>$b$bObozują tam spore siły gnoli, a z tego, co mówisz, to twarde sztuki. Zdobycie tych informacji na pewno nie było łatwe.$b$bProszę, $N. Jesteśmy wdzięczni za twoją pomoc.$b$bA jeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, porozmawiaj z marszałkiem Marrisem i sędzią Solomonem w Jeziernych Włościach. Nasze położenie jest coraz bardziej rozpaczliwe – na pewno obaj będą cię potrzebować.', 0),
(248, 'plPL', 'To odpowiednie naczynie dla Glifu Azory – dzięki niemu Theocritus zajrzy w umysły tych, którzy przebywają w Twierdzy Kamiennej Straży.', 0),
(386, 'plPL', 'Targorr Straszliwy w końcu spotkał swój los. Co do mnie, cieszę się, że ta bestia wie teraz, jak to jest znaleźć się w bezlitosnym uścisku śmierci. Dobrze się $gspisałeś:spisałaś;, $N. Czasem najprawdziwszą sprawiedliwość można znaleźć tylko poza salą sądową, z dala od zamglonego spojrzenia polityki.', 0),
(1699, 'plPL', 'Udało ci się! Brawo! Hip, hip, hurra! Niech żyje $N!', 0),
(2282, 'plPL', '$GRozpracowałeś:Rozpracowałaś; ją, co? Niezła robota, $N.$B$BJeśli teraz zginiesz, możemy spać spokojnie, wiedząc, że to przez twoją głupotę, a nie brak doświadczenia.', 0),
(2358, 'plPL', 'Odmówić Krukowisku tego artefaktu to jak zaprzeć się własnego istnienia. Dobra robota, $N. Być może jeszcze staniesz w szeregach zabójców z Krukowiska.$B$BGdy jako młody łotrzyk przemierzałem Mroczne Wybrzeże, odkryłem herbatę, która przywraca energię w walce. Przez lata dobrze mi służyła, a teraz daję ci skosztować ostowej herbaty. Pij ją, gdy opadniesz z sił, $N, i znów walcz z wigorem!$B$B', 0),
(3741, 'plPL', 'Dziękuję, że $gznalazłeś:znalazłaś; mój naszyjnik, $gpanie:pani; $N... jesteś bardzo $gmiły:miła;! Mój kotek też ci dziękuje – prawda, Effsee?', 0),
(11751, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Górach Rudej Grani!', 0),
(11822, 'plPL', 'Uczcij płomień Gór Rudej Grani!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(19, 'plPL', 'Orkowie z Czarnej Skały wciąż na nas napierają. Ale czy przynajmniej $gpozbyłeś:pozbyłaś; nas Tharil\'zuna?', 0),
(20, 'plPL', '$GZabijałeś:Zabijałaś; orków, $N? Jeśli tak, to pokaż...', 0),
(34, 'plPL', 'Czy Brzuchożer wciąż grasuje, czy może $gzdołałeś:zdołałaś; raz na zawsze uwolnić Jezierne Włości od tego szkodnika?', 0),
(89, 'plPL', 'Ten most sam się nie zbuduje! No, gdzie są te żelazne piki i żelazne nity?', 0),
(91, 'plPL', 'Oddaj mi 10 wisiorów Cienioskórych, a zostaniesz $gnagrodzony:nagrodzona;.', 0),
(92, 'plPL', 'Wciąż potrzebuję pięciu kawałków twardego mięsa kondora, pięciu ryjów wielkich krwawokłów i pięciu porcji chrupiącego pajęczego mięsa.', 0),
(115, 'plPL', 'Jak idzie walka z miotaczami cieni? $GZnalazłeś:Znalazłaś; kule głębokiej nocy?', 0),
(116, 'plPL', 'Musisz odebrać baryłkę lagera Gromowarów od Grimbooze\'a Gromowara na wzgórzach Zachodniego Skraju, beczułkę merlota z Wichrogrodu, butelkę bimbru z Mrocznych Włości i bukłak słodkiego rumu ze Złotych Włości. Przynieś mi to wszystko, a dopilnuję, żebyś $gdostał:dostała; nagrodę.', 0),
(122, 'plPL', 'Wiem, że ten chciwiec Argus przyśle kogoś po swoje łuski, jeśli wkrótce ich nie oddam. $GZnalazłeś:Znalazłaś; już te łuski?', 0),
(124, 'plPL', 'Moje konie wciąż są płochliwe, a nocami nadal słyszę to przeklęte wilcze wycie. Proszę, $N, zrób coś z tymi gnolami!', 0),
(125, 'plPL', '$GZdołałeś:Zdołałaś; znaleźć moje narzędzia?', 0),
(126, 'plPL', 'Wyjec to groźna bestia, $N. Jeśli nie jesteś na niego $ggotów:gotowa;, rozumiem.', 0),
(127, 'plPL', 'Masz dla mnie bassy słoneczne, co?', 0),
(128, 'plPL', 'Wróć, gdy zabijesz 15 czempionów Czarnej Skały.', 0),
(129, 'plPL', 'Darcy przysłała mi posiłek, tak? Ma takie dobre serce. No... dawaj!', 0),
(131, 'plPL', 'Witaj ponownie, $N. Czy Parkerowi smakował posiłek, który mu posłałam?', 0),
(145, 'plPL', 'Wyglądasz, jakbyś $gprzybył:przybyła; z daleka, $N. Co cię sprowadza do Mrocznych Włości?', 0),
(146, 'plPL', 'Ach, dobrze cię znowu widzieć, posłańcze. Czy mam powiadomić marszałka, że Nocna Straż wyruszyła już z Mrocznych Włości?', 0),
(150, 'plPL', 'Masz te płetwy? Pośpiesz się, musimy przegnać murloki z jeziora!', 0),
(169, 'plPL', 'Co tam masz?', 0),
(180, 'plPL', 'Z jakimi wieściami stajesz przed sądem?', 0),
(246, 'plPL', 'Wybacz, $N, ale mamy tu pełne ręce roboty. Jeśli nie masz nic do zameldowania, muszę zająć się innymi sprawami.', 0),
(248, 'plPL', 'W tym słoju był kiedyś cuchnący trunek, ale teraz stoi pusty i zapomniany na dwóch beczkach.', 0),
(386, 'plPL', '$GByłeś:Byłaś; już w Wichrogrodzie, w Kazamatach? Obawiam się, że ten podstęp, który tak długo utrzymuje Targorra Straszliwego przy życiu, w końcu da mu wolność. Został skazany na śmierć, $N, a nie po to, by być pionkiem w politycznej grze dla kaprysu jakiegoś szlachcica.', 0),
(2282, 'plPL', 'Czy zapomniałem wspomnieć o orkach?$B$BPodobno węszą w okolicy młyna.', 0),
(2358, 'plPL', 'Masz rogi tego demonicznego księcia?', 0),
(3741, 'plPL', 'Cześć. Tęsknię za moim naszyjnikiem. Dostałam go od taty. Tata mówi, że w jeziorze są potwory. $GPobiłeś:Pobiłaś; jakieś potwory?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(342, 0, 'plPL', 'Witaj, $N! Zapraszam do mojego skromnego ogrodu. Pogoda ostatnio dopisuje. Miejmy nadzieję, że się utrzyma i zbiory będą obfite.', 0),
(381, 0, 'plPL', 'Bądź $gpozdrowiony:pozdrowiona;, $N. Jeśli przychodzisz w interesach, weź sobie coś do picia, to sobie pogadamy.', 0),
(382, 0, 'plPL', 'Nie mam czasu na pogawędki, $gobywatelu:obywatelko;, ale jeśli chcesz nam pomóc w walce z orkami, znajdę dla ciebie zajęcie.', 0),
(464, 0, 'plPL', 'Witaj, $N. Złe to czasy, $gprzyjacielu:przyjaciółko;, bo nasze miasto jest oblężone! Orkowie z Czarnej Skały atakują z Twierdzy Kamiennej Straży, Cienioskórzy czają się nad Wieżą Ilgalara, a sfora gnoli z Rudej Grani rośnie w siłę. Mam nadzieję, że nie przybywasz tu na wypoczynek...', 0),
(900, 0, 'plPL', 'Co cię sprowadza przed oblicze sądu Jeziernych Włości i Szanownego Sędziego Solomona?', 0);
