INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(51, 'plPL', 'Lordzie Ebonlocke – osada Jezierne Włości pokornie prosi o pomoc Nocnej Straży. Jesteśmy oblężeni zarówno przez orków z Czarnej Skały, jak i przez gnole z Cienioskórych, na usługach Morgantha. Nie prosiłbym, gdyby nasze położenie nie było poważne. Czekamy na pomoc z Wichrogrodu, lecz dopóki nie nadejdzie, błagam cię o wsparcie. Gdy granice królestwa zostaną przełamane, cała ludzkość znajdzie się w niebezpieczeństwie. Sędzia Solomon', 0),
(52, 'plPL', 'Wysoki Sądzie!\n\nZ przykrością zawiadamiam, że Nocna Straż nie może obecnie opuścić swojego posterunku w Mrocznych Włościach. Być może nie wiesz, że Wichrogród nie zapewnia już wsparcia wojskowego w tym regionie. Nocną Straż utworzyli i wyszkolili wyłącznie mieszkańcy lasu, by bronić Mrocznych Włości pod nieobecność Wichrogrodu. Bez Straży miasto by upadło. Życzę ci powodzenia w twoim trudnym położeniu.\n\n– Lord Ello Ebonlocke\n', 0),
(245, 'plPL', 'Zaginiony: kapral Keeshan$B$BKapral Keeshan był ostatnio widziany podczas krwawej bitwy o Twierdzę Kamiennej Straży. Według doniesień został uprowadzony przez orków z Czarnej Skały.$B$BPrzypuszcza się, że kapral Keeshan jest przetrzymywany jako jeniec wojenny w obozowisku Czarnej Skały na północ od Jeziernych Włości, tuż na zachód od przełęczy prowadzącej na Płonące Stepy.$B$BZ polecenia sędziego Solomona każdy, kto pomoże odnaleźć kaprala Keeshana, zostanie wynagrodzony przez marszałka Marrisa.', 0),
(992, 'plPL', 'Okaziciel niniejszego certyfikatu ma prawo do szacunku i poważania, jakie należą się każdemu pierwszorzędnemu złodziejaszkowi i rabusiowi.', 0),
(1772, 'plPL', 'Wyrmthalaku, otrzymałem od twojego pana, Nefariana, bezpośredni rozkaz, by ukarać cię wedle mojego uznania, jeśli jeszcze jacyś intruzi przedostaną się do cytadeli. Nie zapominaj, kto ci rozkazuje, gadzie. Syn Czarnorękiego: mistrz ostrza i bitwy. Jedyny prawdziwy wódz. – Rwij', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(25, 'plPL', 'Moje rany są poważne. Wybacz, że idę tak wolno, ale obrażenia nie pozwalają mi iść szybciej.', '', 0),
(26, 'plPL', 'Ach, nareszcie świeże powietrze! Muszę chwilę odpocząć.', '', 0),
(27, 'plPL', 'Czarna Skała roi się w tych okolicach. Postaram się dotrzymać ci kroku. Ruszajmy!', '', 0),
(29, 'plPL', 'Panie marszałku Marris! Kapral Keeshan z 12. Pułku Szabli wrócił z bitwy i melduje się na służbę!', '', 0),
(30, 'plPL', '$GDzielny poszukiwaczu:Dzielna poszukiwaczko; przygód, dziękuję za ratunek! Jestem pewien, że marszałek Marris wynagrodzi twój dobry uczynek.', '', 0),
(45, 'plPL', 'Nic nie bierze...', '', 0),
(46, 'plPL', 'Chodź, rybko, rybko... chodź do tatusia.', '', 0),
(47, 'plPL', 'Przysuń stołek i napij się!', '', 0),
(48, 'plPL', 'Butelki zakurzone, ale trunek wchodzi gładko!', '', 0),
(49, 'plPL', '', 'Oby posiłki z Wichrogrodu wkrótce się zjawiły...', 0),
(51, 'plPL', 'Gdzie są te posiłki z Wichrogrodu? Donoszą o wzmożonych ruchach Czarnej Skały na wschodzie.', '', 0),
(52, 'plPL', 'Wciąż ani śladu 2. Batalionu z Wichrogrodu. Napływają meldunki o ruchach Cienioskórych na północnym wschodzie.', '', 0),
(53, 'plPL', 'Marszałek Marris lada chwila spodziewa się rezerwy z Wichrogrodu...', '', 0),
(63, 'plPL', 'Nieumarli pełzają po całej krainie. Gdzie jest Armia Wichrogrodu?', '', 0),
(64, 'plPL', 'Sama Nocna Straż nie będzie nas chronić wiecznie. Potrzebujemy wsparcia Armii Wichrogrodu.', '', 0),
(270, 'plPL', 'To ponure wieści i obawiam się, że mają związek ze sprawkami, w które $n $gwplątał:wplątała; się z Balsamistą.', '', 0),
(271, 'plPL', 'Wartowniku, przekaż Althei, że przeciw naszemu miastu zbiera się straszliwe zagrożenie. Musimy się przygotować!', '', 0),
(465, 'plPL', 'Głupcze! Klan Czarnej Skały zatańczy na twoim grobie!', '', 0),
(466, 'plPL', 'Głupcze! Nie dorównasz mojej potędze!', '', 0),
(467, 'plPL', 'Jestem Gath\'Ilzogg! A ty stoisz na skraju śmierci!', '', 0),
(468, 'plPL', 'Śmierć dla $n! Niech żyje klan Czarnej Skały!', '', 0),
(469, 'plPL', 'Kto śmie wtargnąć do klanu Czarnej Skały? Śmierć intruzowi!', '', 0),
(470, 'plPL', 'Mizeroto! Nie dorównasz klanowi Czarnej Skały!', '', 0),
(471, 'plPL', 'Głupcze! Połamię ci te słabe kości!', '', 0),
(472, 'plPL', 'Niech żyje potężny klan Czarnej Skały!', '', 0),
(703, 'plPL', '', 'Witaj, Antonio. Dobrze widzieć, że znowu bezpiecznie tu dotarłeś. Daj znać, jeśli czegoś potrzebujesz.', 0),
(715, 'plPL', '', 'Uważaj na siebie, Antonio. Do zobaczenia za tydzień.', 0),
(1874, 'plPL', 'Poczuj potęgę orków z Czarnej Skały!', 'Poczuj potęgę orków z Czarnej Skały!', 0),
(1875, 'plPL', 'Nie masz szans z orkami z Czarnej Skały!', 'Nie masz szans z orkami z Czarnej Skały!', 0),
(4615, 'plPL', '', 'Chyba mój naszyjnik wpadł do jeziora. Dostałam go od taty, a teraz tata będzie zły.', 0),
(4616, 'plPL', '', 'Dziękuję, $gproszę pana:proszę pani;, że $gznalazł pan:znalazła pani; mój naszyjnik! $gJest pan najlepszy:Jest pani najlepsza;!', 0),
(4618, 'plPL', 'Dzień dobry, $gproszę pana:proszę pani;... czy ma $gpan:pani; chwilkę, żeby nam pomóc? Proszę?', '', 0),
(4627, 'plPL', 'Miau!', '', 0),
(4628, 'plPL', '', 'Umiem mówić po kociemu, a Effsee mówi, że dziękuje.', 0);
